const evidence={Biblia:'Hiob nie zna przyczyny próby, Kohelet obserwuje przemijanie, a Apokalipsa łączy katastrofę z nadzieją odnowy.',Mitologia:'Prometeusz, Syzyf, Orfeusz i Ikar pokazują modelowe wybory oraz ich konsekwencje.',Iliada:'Achilles zna swój los, lecz wybiera krótkie życie i sławę; Priam odzyskuje ciało Hektora dzięki odwadze i człowieczeństwu.','Lament świętokrzyski':'Maryja mówi jak bezradna matka, nie odległa królowa; emocjonalny monolog humanizuje sacrum.','Rozmowa Mistrza Polikarpa ze Śmiercią':'Śmierć wylicza przedstawicieli wszystkich stanów, przypominając o równości i marności pozycji.','Pieśń o Rolandzie':'Roland jest wierny Bogu, władcy i ojczyźnie, lecz jego duma opóźnia wezwanie pomocy.','Satyry Ignacego Krasickiego':'Karykatura, ironia i wyolbrzymienie ujawniają pijaństwo, modę, hipokryzję i bezmyślność.','Romantyczność':'Karusia doświadcza obecności Jasia, a spór narratora ze Starcem przeciwstawia „czucie i wiarę” szkiełku i oku.','Ballady Mickiewicza':'W „Świteziance” i „Lilijach” zbrodnia zostaje ukarana przez siły natury i porządek moralny.',Ferdydurke:'Józio jest „upupiany”; szkoła, Młodziakowie i dwór narzucają mu kolejne formy.', 'Proszę państwa do gazu':'Tadek przystosowuje się do obozowych reguł; system rozmywa empatię i zmusza ofiary do udziału w machinie.', 'Górą Edek':'Tytułowy Edek nawiązuje do bohatera „Tanga”; intertekstualność pokazuje powrót brutalnej siły w codzienności.',Miejsce:'Zburzona cerkiew istnieje w pamięci narratora i mieszkańców; miejsce przechowuje historię nawet po zniknięciu budynku.','Profesor Andrews w Warszawie':'Obcokrajowiec nie zna języka ani realiów stanu wojennego, dlatego codzienność staje się obca i absurdalna.','Podróże z Herodotem':'Podróż poszerza język, perspektywę i rozumienie innych kultur; Herodot staje się przewodnikiem Kapuścińskiego.'};
const qContext=t=>/wład|państw|totalit|propagand|wolno/.test(t)?'„Rok 1984” lub historyczny kontekst totalitaryzmu':/win|kar|zbrod|sumieni/.test(t)?'„Makbet” albo „Zbrodnia i kara”':/miło|rodzic|matk/.test(t)?'„Treny” lub „Lalka”':/naród|Polsk|niepodleg|zabor/.test(t)?'„Wesele”, „Dziady III” albo historia Polski':/cierp|śmier|skrajn|poświę/.test(t)?'Księga Hioba, „Dżuma” lub „Inny świat”':/bunt|pokole|norm/.test(t)?'„Antygona” albo „Tango”':/pamię|miejsce|podróż/.test(t)?'„Pan Tadeusz” – pamięć i tożsamość':'wybrany mit, Biblia albo druga lektura z podobnym motywem';
const getBook=n=>books.find(b=>n.toLowerCase().includes(b[0].toLowerCase().replace(' cz. III',''))) ;
function qThesis(t){const s=t.toLowerCase();if(/cierp|śmier/.test(s))return'Cierpienie odsłania hierarchię wartości człowieka: może go złamać, ale może też prowadzić do solidarności, dojrzewania lub obrony godności.';if(/wład|państw|totalit|propagand|nowomow/.test(s))return'Władza pozbawiona kontroli dąży nie tylko do posłuszeństwa, lecz także do przejęcia języka, pamięci i sposobu myślenia jednostki.';if(/miło/.test(s))return'Miłość staje się siłą budującą, gdy uznaje podmiotowość drugiej osoby; idealizacja, egoizm lub przemoc zmieniają ją w źródło klęski.';if(/bunt|wolno|norm/.test(s))return'Bunt ma wartość, gdy broni rozpoznawalnych zasad i łączy się z odpowiedzialnością; sam sprzeciw nie gwarantuje wolności ani zwycięstwa.';if(/win|kar|zbrod|sumieni/.test(s))return'Kara zaczyna się często przed wyrokiem: świadomość winy niszczy wewnętrzny spokój, a próba ukrycia zbrodni prowadzi do następnych przekroczeń.';if(/ojczy|patriot|naród|polsk/.test(s))return'Patriotyzm sprawdza się w odpowiedzialnym działaniu dla wspólnoty, nie w samych deklaracjach, dlatego literatura pokazuje zarówno ofiarność, jak i narodowe słabości.';if(/przeznacz|los|fatum/.test(s))return'Człowiek nie wybiera wszystkich okoliczności, ale odpowiada za sposób, w jaki reaguje na los; tragizm rodzi się wtedy, gdy każda dostępna decyzja ma niszczącą cenę.';if(/marzen|utopi|doskona/.test(s))return'Marzenie może wyznaczać kierunek działania, lecz oderwane od wiedzy o człowieku i rzeczywistości prowadzi do rozczarowania albo przemocy.';if(/przyjaź|solidar|poświę/.test(s))return'Więź z drugim człowiekiem pozwala przekroczyć egoizm, szczególnie w sytuacji granicznej, lecz wymaga dobrowolnej odpowiedzialności i realnego działania.';return`Literatura pokazuje, że problem „${t}” ujawnia się najpełniej w decyzjach bohatera oraz ich zamierzonych i niezamierzonych konsekwencjach.`}
function qModelAnswer(q){const b=getBook(q[1]);const ev=evidence[q[1]]||(b?b[3]:'Bohater zostaje postawiony w sytuacji, w której musi wybrać między własnym bezpieczeństwem a uznawanymi wartościami.');const ctx=qContext(q[2]);const thesis=qThesis(q[2]);return `<div class="oral-model-label">Gotowa odpowiedź wzorcowa</div><p>Zagadnienie <b>„${q[2]}”</b> dotyczy tego, jak okoliczności, wartości i relacje z innymi wpływają na ludzkie decyzje. Uważam, że ${thesis.charAt(0).toLowerCase()+thesis.slice(1)}</p><p>Potwierdza to <b>„${q[1]}”</b>. ${ev} Nie jest to wyłącznie element fabuły. Sytuacja ujawnia motywację postaci, granice jej wolności oraz cenę podjętej decyzji. Bohater zostaje oceniony nie przez swoje deklaracje, lecz przez działanie i jego skutki. Właśnie dlatego przykład odpowiada na pytanie: pokazuje mechanizm, w którym problem staje się realnym doświadczeniem człowieka.</p><p>Funkcjonalnym kontekstem może być <b>${ctx}</b>. Oba ujęcia łączy próba wartości dokonująca się w konkretnej sytuacji, ale mogą różnić się źródłem presji, możliwością wyboru i ostatecznym rezultatem. Takie porównanie poszerza odpowiedź: ten sam problem nie prowadzi wszystkich postaci do identycznego zachowania, ponieważ znaczenie mają ich hierarchia wartości, świadomość i gotowość poniesienia konsekwencji.</p><p><b>Wniosek:</b> literatura nie daje tu jednej prostej recepty. Pokazuje jednak, że o człowieku najwięcej mówią decyzje podejmowane w chwili próby. Ostateczny sens zagadnienia „${q[2]}” ujawnia się więc w związku między wyborem, jego ceną oraz wpływem na innych.</p>`}
function qAnswer(q){const b=getBook(q[1]);const ev=evidence[q[1]]||(b?b[3]:'Wskaż konkretną decyzję bohatera, jej przyczynę i konsekwencję.');const ctx=qContext(q[2]);return `<div class="oral-skeleton"><h3>Plan odpowiedzi</h3><p><b>1. Wprowadzenie do problemu:</b> Wyjaśnij własnymi słowami pojęcie zawarte w pytaniu „${q[2]}”.</p><p><b>2. Teza:</b> ${qThesis(q[2])}</p><p><b>3. Konkretny materiał z utworu:</b> ${ev}</p><p><b>4. Analiza:</b> Nazwij motywację postaci, jej wybór oraz skutek.</p><p><b>5. Kontekst:</b> ${ctx}. Wskaż podobieństwo albo różnicę.</p><p><b>6. Wniosek:</b> Wróć bezpośrednio do pytania.</p></div><details class="oral-model"><summary>Pokaż gotową, wypracowaną odpowiedź</summary><div class="oral-model-body">${qModelAnswer(q)}</div></details>`}
const nav=[['start','Plan nauki'],['exam','Matura podstawowa – arkusz'],['books','Lektury – duże opracowania'],['shortworks','Pozostałe lektury CKE'],['poetry','Poezja obowiązkowa'],['motifs','Motywy – bank argumentów'],['oral','76 pytań jawnych CKE'],['mynotes','Moje notatki i komentarze'],['heroes','Bohaterowie i przemiany'],['contexts','Konteksty uniwersalne'],['eras','Epoki – pełne karty'],['philosophy','Filozofia'],['analysis','Jak analizować tekst'],['devices','Środki stylistyczne'],['genres','Gatunki literackie'],['essay','Wypracowanie i argumentacja'],['speaking','Schemat odpowiedzi ustnej']];
let state={page:'start',query:'',selectedOnly:false};
