function check(id,label){return `<label class="check"><input type="checkbox" data-done="${id}" ${done[id]?'checked':''}><span>${label}</span></label>`}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function noteBox(id,title){return `<div class="comment-box"><label for="note-${id}">Moja notatka / komentarz <small>zapis automatyczny</small></label><textarea id="note-${id}" data-note="${id}" data-title="${esc(title)}" placeholder="Dopisz skojarzenie, cytat, argument albo własny komentarz…">${esc(notes[id]||'')}</textarea><div class="note-saved" aria-live="polite"></div></div>`}
function quizButton(id){return `<button type="button" class="quiz-launch" data-quiz="${id}">✦ Quiz: 5 pytań <small>z puli 50</small></button>`}
function annotationsBox(id){const items=highlights[id]||[];return `<section class="annotations" data-annotations="${id}"><h3>Moja notatka z zaznaczeń</h3><p class="annotations-help">Zaznacz tekst powyżej myszką, wybierz podświetlenie lub dodanie notatki. Treść poniżej możesz dowolnie edytować.</p>${items.length?items.map(h=>`<div class="annotation-card"><blockquote class="annotation-quote">„${esc(h.quote)}”</blockquote><textarea data-annotation-note="${id}" data-highlight-id="${h.id}" placeholder="Dopisz własne wyjaśnienie, skojarzenie lub argument…">${esc(h.note||'')}</textarea><div class="annotation-actions"><span class="note-saved">Zapis automatyczny</span><button class="delete-annotation" data-delete-highlight="${id}" data-highlight-id="${h.id}">Usuń</button></div></div>`).join(''):'<div class="annotations-empty">Nie masz jeszcze zaznaczonych fragmentów.</div>'}</section>`}
function renderNav(){navEl.innerHTML=nav.map(([id,n],i)=>`${i===0||i===1||i===3?`<div class="nav-title">${i===0?'START':i===1?'NAUKA':'MATURA USTNA'}</div>`:''}<button data-page="${id}" class="${state.page===id?'active':''}">${n}</button>`).join('')}
function start(){return `<div class="hero"><h2>Twoje centrum powtórek ♡</h2><p>Pełna baza do matury 2027: lektury, obowiązkowa poezja, motywy, epoki, analiza tekstu, argumentacja i pytania jawne. Zaznaczaj tekst i twórz własne notatki pod każdym działem.</p></div><div class="stats"><div class="stat"><b>32</b>opracowania lektur</div><div class="stat"><b>76</b>pytań jawnych CKE</div><div class="stat"><b>31</b>motywów z argumentami</div></div><h2 class="section-title">Jak uczyć się skutecznie</h2><div class="grid"><div class="card"><h3>1. Zrozum</h3><p>Najpierw opanuj ciąg przyczynowo-skutkowy: sytuacja → decyzja bohatera → powód → konsekwencja. Sama lista wydarzeń nie wystarczy.</p></div><div class="card"><h3>2. Połącz</h3><p>Do każdej lektury przypisz kilka motywów, jedną scenę-klucz i dwa konteksty. Jedna dobrze znana lektura obsłuży wiele tematów.</p></div><div class="card"><h3>3. Argumentuj</h3><p>Nie streszczaj. Nazwij prawidłowość, podaj scenę, wyjaśnij jej znaczenie i wróć do tezy.</p></div></div><div class="card setup-card"><h3>Najważniejsza kolejność</h3><p><b>Lektury i poezja → motywy → epoki → wypracowanie → pytania ustne.</b> Po każdym dziale spróbuj powiedzieć z pamięci trzy zdania: tezę, przykład i wniosek.</p></div>`}
function conceptsFor(title){const data=window.LITERARY_CONCEPTS||{definitions:{},books:{}};const terms=data.books[title]||['Motyw literacki','Symbol'];return `<section class="key-concepts"><h3>Kluczowe pojęcia do tej lektury</h3><div class="concept-list">${terms.map(term=>`<p><b>${term}</b> – ${data.definitions[term]||''}</p>`).join('')}</div></section>`}
function booksView(){return books.map((b,i)=>`<article class="card book" data-id="b${i}" data-search="${b.join(' ')} ${((window.LITERARY_CONCEPTS?.books||{})[b[0]]||[]).join(' ')} ${esc(notes['b'+i]||'')} ${(highlights['b'+i]||[]).map(h=>h.quote+' '+h.note).join(' ')}"><div class="selectable-text"><div class="book-head"><div class="book-no">${i+1}</div><div><h2>${b[0]}</h2><div class="meta">${b[1]} • ${b[2]}</div>${b.slice(5).flatMap(x=>x.match(/[„”A-ZŁŚŻŹĆŃÓ][^,;.]{2,22}/g)||[]).slice(0,4).map(x=>`<span class="tag">${x.replace(/[„”]/g,'')}</span>`).join('')}</div></div><div class="note-grid"><div class="note wide"><h3>Fabuła: co, dlaczego, konsekwencje</h3><p>${b[3]}</p></div><div class="note"><h3>Bohater: cel, problem, zmiana</h3><p>${b[4]}</p></div><div class="note"><h3>Motywy i symbole</h3><p>${b[5]}</p></div><div class="note"><h3>Problematyka</h3><p>${b[6]}</p></div><div class="note"><h3>Konteksty – gdzie użyć</h3><p>${b[7]}</p></div></div>${conceptsFor(b[0])}</div><div class="quiz-row">${quizButton('b'+i)}</div>${check('b'+i,'Umiem omówić tę lekturę bez zaglądania do notatki')}${annotationsBox('b'+i)}</article>`).join('')}
function tableView(data,heads){return `<div class="card">${data.map(r=>`<div class="motif-row" data-search="${r.join(' ')}"><b>${r[0]}</b><span>${r[1]}</span><span>${r[2]}</span></div>`).join('')}</div>`}
const expanded=window.MATURA_EXPANDED||{shortWorks:[],poems:[],philosophies:[],genres:[]};
function normalizeText(value=''){return String(value).toLowerCase().replace(/[łŁ]/g,'l').replace(/[đĐ]/g,'d').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9\s]/g,' ').replace(/\s+/g,' ').trim()}
function editDistance(a,b){if(!a)return b.length;if(!b)return a.length;const row=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){let prev=row[0];row[0]=i;for(let j=1;j<=b.length;j++){const old=row[j];row[j]=Math.min(row[j]+1,row[j-1]+1,prev+(a[i-1]===b[j-1]?0:1));prev=old}}return row[b.length]}
function globalSearchIndex(){return [
  ...books.map((x,i)=>({page:'books',id:'b'+i,title:x[0],section:'Duże opracowania lektur',text:x.join(' ')})),
  ...expanded.shortWorks.map((x,i)=>({page:'shortworks',id:'s'+i,title:x.t,section:'Pozostałe lektury CKE',text:Object.values(x).join(' ')})),
  ...expanded.poems.map((x,i)=>({page:'poetry',id:'p'+i,title:x[0],section:'Poezja obowiązkowa',text:x.join(' ')})),
  ...questions.map(x=>({page:'oral',id:'q'+x[0],title:x[0]+'. '+x[2],section:'Pytania jawne • '+x[1],text:x.join(' ')})),
  ...motifNames.map((x,i)=>({page:'motifs',id:'motif-'+i,title:x,section:'Motywy literackie',text:x+' '+(motifExamples[x]||'')})),
  ...expanded.philosophies.map((x,i)=>({page:'philosophy',id:'philosophy-'+i,title:x[0],section:'Filozofia',text:x.join(' ')})),
  ...expanded.genres.map((x,i)=>({page:'genres',id:'genre-'+i,title:x[0],section:'Gatunki literackie',text:x.join(' ')})),
  ...nav.filter(x=>!['start','books','shortworks','poetry','oral','mynotes'].includes(x[0])).map(x=>({page:x[0],id:null,title:x[1],section:'Dział',text:x[1]}))
]}
function searchScore(item,query){const q=normalizeText(query),title=normalizeText(item.title),text=normalizeText(item.text);if(!q)return 0;if(title===q)return 1200;if(title.startsWith(q))return 950-q.length;if(title.includes(q))return 820-q.length;if(text.includes(q))return 520;let best=0;for(const word of title.split(' ').concat(text.split(' ').slice(0,90))){if(Math.abs(word.length-q.length)>3)continue;const similarity=1-editDistance(q,word)/Math.max(q.length,word.length,1);best=Math.max(best,similarity)}return best>=.58?Math.round(best*420):0}
function emphasizeResult(title,query){const clean=normalizeText(title),q=normalizeText(query),at=clean.indexOf(q);if(at<0)return esc(title);return esc(title.slice(0,at))+'<mark>'+esc(title.slice(at,at+q.length))+'</mark>'+esc(title.slice(at+q.length))}
function showGlobalResults(query){const box=document.querySelector('#searchResults'),q=normalizeText(query);if(q.length<2){box.classList.remove('show');box.innerHTML='';return}const found=globalSearchIndex().map(item=>({...item,score:searchScore(item,q)})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score||a.title.localeCompare(b.title,'pl')).slice(0,12);box.innerHTML=found.length?found.map((x,i)=>`<button class="search-result${i===0?' active':''}" role="option" data-search-jump="${esc(x.page)}" data-search-id="${esc(x.id||'')}" data-search-title="${esc(x.title)}"><strong>${emphasizeResult(x.title,q)}</strong><small>${esc(x.section)}</small></button>`).join(''):'<div class="search-empty">Nie znaleziono. Spróbuj krótszego hasła.</div>';box.classList.add('show')}
function highlightSearchTerm(root,query){if(!root||!query)return;const q=normalizeText(query),walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(node.parentElement.closest('mark,textarea,button,.annotations'))continue;const normalized=normalizeText(node.data),at=normalized.indexOf(q);if(at<0)continue;const before=node.splitText(at),after=before.splitText(q.length),mark=document.createElement('mark');mark.className='search-term-highlight';before.replaceWith(mark);mark.append(before);void after;break}}
function openSearchResult(page,id,title){state.page=page;state.query=document.querySelector('#search').value;document.querySelector('#searchResults').classList.remove('show');render();setTimeout(()=>{const el=id?document.querySelector(`[data-id="${id}"],[data-result-id="${id}"]`):content;if(el){if(el.tagName==='DETAILS')el.open=true;el.style.display='';el.classList.add('search-target-flash');highlightSearchTerm(el,state.query||title);window.scrollTo({top:Math.max(0,el.getBoundingClientRect().top+window.scrollY-18),behavior:'smooth'});setTimeout(()=>el.classList.remove('search-target-flash'),1900)}},60)}
function shortWorksView(){return `<div class="hero"><h2>Krótsze opracowania tekstów z wykazu CKE</h2><p>Każda karta prowadzi od fabuły lub problemu przez bohatera i motywy do gotowego zastosowania w argumentacji.</p></div>${expanded.shortWorks.map((w,i)=>`<article class="card book" data-id="s${i}" data-search="${Object.values(w).join(' ')} ${((window.LITERARY_CONCEPTS?.books||{})[w.t]||[]).join(' ')}"><div class="selectable-text"><div class="book-head"><div class="book-no">${i+1}</div><div><h2>${w.t}</h2><div class="meta">${w.a} • ${w.m}</div></div></div><div class="note-grid"><div class="note wide"><h3>Fabuła / główny problem</h3><p>${w.p}</p></div><div class="note"><h3>Bohaterowie i ich postawy</h3><p>${w.h}</p></div><div class="note"><h3>Najważniejsze motywy</h3><p>${w.m2}</p></div><div class="note"><h3>Przesłanie i interpretacja</h3><p>${w.m3}</p></div><div class="note"><h3>Jak wykorzystać na maturze?</h3><p>Postaw tezę związaną z jednym z wymienionych motywów, przywołaj konkretną sytuację opisaną w karcie i wyjaśnij jej skutek. Jako kontekst dobierz utwór wskazany w przesłaniu.</p></div></div>${conceptsFor(w.t)}</div><div class="quiz-row">${quizButton('s'+i)}</div>${check('s'+i,'Umiem streścić problem i wykorzystać ten tekst jako argument')}${annotationsBox('s'+i)}</article>`).join('')}`}
function quizWorks(){const large=books.map((b,i)=>({key:'b'+i,title:b[0],parts:[b[3],b[4],b[5],b[6],b[7]]}));const short=expanded.shortWorks.map((w,i)=>({key:'s'+i,title:w.t,parts:[w.p,w.h,w.m2,w.m3,`${w.a} • ${w.m}`]}));return [...large,...short]}
const quizLabels=['fabuły, przyczyn i konsekwencji','bohaterów, ich celów i przemian','motywów oraz symboli','problematyki i przesłania','kontekstów, autora lub gatunku'];
const quizPrompts=['Które stwierdzenie poprawnie opisuje','Wskaż informację zgodną z opracowaniem dotyczącym','Która odpowiedź najlepiej przedstawia','Rozpoznaj właściwe omówienie','Który opis należy połączyć z'];
function seededNumber(text){let n=2166136261;for(const ch of text)n=Math.imul(n^ch.charCodeAt(0),16777619);return n>>>0}
function shuffled(values,seed){const out=[...values];for(let i=out.length-1;i>0;i--){seed=(Math.imul(seed,1664525)+1013904223)>>>0;const j=seed%(i+1);[out[i],out[j]]=[out[j],out[i]]}return out}
function quizBank(key){const works=quizWorks(),target=works.find(w=>w.key===key);if(!target)return[];const others=works.filter(w=>w.key!==key),bank=[];for(let round=0;round<10;round++)for(let category=0;category<5;category++){const correct=target.parts[category],offset=(round*7+category*3)%others.length,distractors=[0,1,2].map(step=>others[(offset+step*5)%others.length].parts[category]).filter(Boolean),options=shuffled([correct,...distractors],seededNumber(`${key}-${category}-${round}`));bank.push({id:`${key}-${category}-${round}`,question:`${quizPrompts[(round+category)%quizPrompts.length]} ${quizLabels[category]} w utworze „${target.title}”?`,options,answer:options.indexOf(correct),explain:correct})}return bank}
function ensureQuizDialog(){let dialog=document.querySelector('#quizDialog');if(dialog)return dialog;document.body.insertAdjacentHTML('beforeend','<dialog id="quizDialog" class="quiz-dialog"><div class="quiz-card"><button type="button" class="close" data-close-quiz aria-label="Zamknij">×</button><div id="quizBody"></div></div></dialog>');return document.querySelector('#quizDialog')}
function startQuiz(key){const bank=quizBank(key);if(!bank.length)return;let used=quizHistory[key]||[];if(bank.filter(q=>!used.includes(q.id)).length<5){used=[];quizHistory[key]=[];toast('Cała pula 50 pytań ukończona — zaczynam nowy cykl')}const available=bank.filter(q=>!used.includes(q.id)),questions=shuffled(available,Date.now()>>>0).slice(0,5),work=quizWorks().find(w=>w.key===key);quizSession={key,title:work.title,questions};const dialog=ensureQuizDialog(),body=dialog.querySelector('#quizBody');body.innerHTML=`<span class="eyebrow">QUIZ Z LEKTURY</span><h2>${esc(work.title)}</h2><p class="quiz-progress">5 pytań • wykorzystano ${used.length} z 50 pytań w bieżącym cyklu</p><form id="quizForm">${questions.map((q,i)=>`<fieldset class="quiz-question"><legend><b>${i+1}.</b> ${esc(q.question)}</legend>${q.options.map((option,j)=>`<label><input type="radio" name="quiz-${i}" value="${j}"><span>${esc(option)}</span></label>`).join('')}</fieldset>`).join('')}<p class="form-error" id="quizError"></p><button type="submit" class="primary">Sprawdź wynik</button></form>`;body.querySelector('#quizForm').onsubmit=submitQuiz;dialog.showModal()}
function submitQuiz(event){event.preventDefault();const form=event.currentTarget,answers=quizSession.questions.map((q,i)=>form.querySelector(`input[name="quiz-${i}"]:checked`)?.value);if(answers.some(x=>x===undefined)){form.querySelector('#quizError').textContent='Zaznacz odpowiedź w każdym z 5 pytań.';return}const results=quizSession.questions.map((q,i)=>({q,chosen:Number(answers[i]),ok:Number(answers[i])===q.answer})),score=results.filter(x=>x.ok).length;quizHistory[quizSession.key]=[...(quizHistory[quizSession.key]||[]),...quizSession.questions.map(q=>q.id)];persist();const percent=score*20,body=document.querySelector('#quizBody');body.innerHTML=`<span class="eyebrow">TWÓJ WYNIK</span><h2>${score}/5 • ${percent}%</h2><p class="quiz-verdict">${score===5?'Świetnie — znasz tę lekturę bardzo dobrze.':score>=4?'Bardzo dobrze. Powtórz tylko wskazany fragment.':score>=3?'Podstawa jest opanowana, ale warto wrócić do błędnych odpowiedzi.':'Wróć do opracowania i spróbuj ponownie po powtórce.'}</p><div class="quiz-results">${results.map((r,i)=>`<div class="quiz-result ${r.ok?'correct':'wrong'}"><h3>${r.ok?'✓':'×'} Pytanie ${i+1}</h3><p><b>Twoja odpowiedź:</b> ${esc(r.q.options[r.chosen])}</p>${r.ok?'':`<p><b>Poprawna odpowiedź:</b> ${esc(r.q.explain)}</p>`}</div>`).join('')}</div><div class="quiz-finish"><button type="button" class="text-btn" data-close-quiz>Zamknij</button><button type="button" class="primary" data-next-quiz="${quizSession.key}">Następne 5 pytań</button></div>`}
function poetryView(){return `<div class="hero"><h2>Poezja – czytaj według stałego schematu</h2><p>O czym? → kto mówi i do kogo? → jaka jest sytuacja? → jakie środki i po co? → jakie przesłanie, motyw, epoka i kontekst?</p></div>${expanded.poems.map((p,i)=>`<article class="card" data-id="p${i}" data-search="${p.join(' ')}"><div class="selectable-text"><h2>${p[0]}</h2><div class="meta">${p[1]} • ${p[2]}</div><div class="poem-grid"><div><h3>O czym?</h3><p>${p[3]}</p></div><div><h3>Podmiot i sytuacja liryczna</h3><p>${p[4]}</p></div><div><h3>Środki i ich funkcja</h3><p>${p[5]}</p></div><div><h3>Przesłanie i motywy</h3><p>${p[6]}</p></div><div><h3>Możliwy kontekst</h3><p>${p[7]}</p></div></div></div>${check('p'+i,'Rozpoznaję utwór i umiem wyjaśnić funkcję środków')}${annotationsBox('p'+i)}</article>`).join('')}`}
const motifNames=['Miłość','Śmierć','Cierpienie','Samotność','Bunt','Władza','Wojna','Ojczyzna','Patriotyzm','Wolność','Zniewolenie','Człowiek wobec Boga','Zło','Wina i kara','Przemiana','Dojrzewanie','Podróż','Natura','Społeczeństwo','Jednostka kontra społeczeństwo','Praca','Pieniądze','Marzenia kontra rzeczywistość','Pamięć','Artysta','Rodzina','Poświęcenie','Granice człowieczeństwa','Totalitaryzm','Absurd','Bunt przeciwko rzeczywistości'];
const motifExamples={Miłość:'„Lalka” – idealizacja Izabeli niszczy Wokulskiego; „Makbet” – więź małżonków zostaje skażona zbrodnią; „Treny” – miłość rodzicielska ujawnia się w żałobie; „Dżuma” – Rambert rezygnuje z prywatnego szczęścia; mit Orfeusza – miłość próbuje przekroczyć śmierć.',Śmierć:'„Antygona”, „Treny”, „Iliada”, „Dżuma”, „Zdążyć przed Panem Bogiem” – śmierć może być losem, stratą, próbą godności albo doświadczeniem masowym.',Cierpienie:'Hiob cierpi bez winy; Kochanowski traci światopogląd; więźniowie łagru i obozu cierpią przez system; Rieux widzi cierpienie niewinnego dziecka.',Samotność:'Konrad izoluje się przez pychę; Wokulski nie należy do żadnej klasy; Raskolnikow odcina się przez teorię; Winston pozostaje bezbronny wobec Partii; Antygona samotnie broni racji.',Bunt:'Antygona przeciw Kreonowi; Prometeusz przeciw bogom; Konrad przeciw Bogu i caratowi; Winston przeciw Partii; Artur przeciw chaosowi rodziców.',Władza:'Kreon absolutyzuje prawo; Makbet zdobywa tron zbrodnią; Senator używa terroru; Partia kontroluje świadomość; Edek przejmuje władzę siłą.',Wojna:'„Iliada”, „Potop”, „Inny świat”, Borowski, Krall – od etosu walki po dehumanizację i walkę o elementarną godność.',Ojczyzna:'Soplicowo jako ojczyzna pamięci; Polska-męczennik w „Dziadach”; niedojrzałe państwo w „Przedwiośniu”; naród niezdolny do czynu w „Weselu”; ofiara w hymnie Krasickiego.',Patriotyzm:'Roland, Kmicic, Konrad, Jacek Soplica i podmiot „Pieśni V” pokazują patriotyzm jako wierność, odpowiedzialność, walkę lub odkupienie.',Wolność:'Antygona wybiera wolność moralną; Konrad walczy o naród; więzień łagru broni wewnętrznej niezależności; Winston przegrywa walkę o prawdę; Cezary szuka sprawiedliwej Polski.',Zniewolenie:'carat w „Dziadach III”; łagier w „Innym świecie”; obóz u Borowskiego; Partia w „Roku 1984”; presja formy w „Ferdydurke”.','Człowiek wobec Boga':'Hiob pyta o sens próby; Konrad oskarża Boga, ksiądz Piotr ufa; Kochanowski przechodzi kryzys; Paneloux interpretuje dżumę; Antygona słucha prawa boskiego.',Zło:'Makbet wybiera zbrodnię; Raskolnikow próbuje ją usprawiedliwić; dżuma oznacza zło powracające; totalitaryzm zamienia zło w system; Edek korzysta z braku norm.','Wina i kara':'Makbet doświadcza lęku i klęski; Raskolnikow cierpi przed wyrokiem; Balladyna usuwa świadków; bohaterowie ballad podlegają moralnemu porządkowi; Kreon płaci utratą rodziny.',Przemiana:'Jacek Soplica odkupuje winę; Kmicic staje się Babiniczem; Raskolnikow rozpoczyna odrodzenie; Rambert wybiera solidarność; Makbet przemienia się w tyrana.',Dojrzewanie:'Cezary traci naiwność; Tadeusz staje się gospodarzem; Kapuściński dojrzewa jako reporter; Józio kwestionuje narzuconą dojrzałość; Wokulski nie przezwycięża romantycznej iluzji.',Podróż:'Kapuściński poznaje Innego; Cezary szuka Polski; Odyseusz jako kontekst wraca do domu; emigranci „Pana Tadeusza” podróżują w pamięci; Andrews doświadcza obcości.',Natura:'w „Chłopach” wyznacza rytm życia; w balladach osądza winnych; w „Panu Tadeuszu” przechowuje ojczyznę; w „Dżumie” epidemia obnaża kondycję ludzi; chochoł łączy uśpienie z możliwością odrodzenia.',Społeczeństwo:'„Lalka” ujawnia bariery klasowe; „Wesele” brak wspólnoty; „Chłopi” siłę gromady; „Przedwiośnie” nierówność; „Tango” kryzys norm.','Jednostka kontra społeczeństwo':'Antygona przeciw państwu; Wokulski wobec klas; Jagna wobec gromady; Winston wobec Partii; Józio wobec formy.',Praca:'Wokulski i Ochocki widzą drogę rozwoju; chłopi – podstawę życia; łagier – narzędzie wyniszczenia; Rieux – uczciwy obowiązek; Harpagon podporządkowuje działanie pieniądzom.',Pieniądze:'Harpagon czyni z nich cel; Wokulski używa ich do awansu i pomocy; Łęccy żyją pozorem; Reymont pokazuje ziemię jako kapitał; bieda wpływa na Sonię.', 'Marzenia kontra rzeczywistość':'Wokulski idealizuje Izabelę; Cezary zderza szklane domy z Polską; bohaterowie „Wesela” marzą o czynie; Winston przecenia możliwość oporu; Artur nie ma idei zdolnej poprzeć formę.',Pamięć:'„Pan Tadeusz” ocala ojczyznę; Rzecki zapisuje odchodzący świat; Edelman i Herling dają świadectwo; „Miejsce” odtwarza utraconą kulturę; Partia Orwella niszczy przeszłość.',Artysta:'Konrad pragnie władzy nad duszami; Słowacki zostawia testament; Wyspiański diagnozuje wspólnotę przez symbol; Orfeusz próbuje zwyciężyć śmierć sztuką; poeta może być świadkiem historii.',Rodzina:'Antygona wybiera obowiązek wobec brata; Kreon traci syna i żonę; Kochanowski przeżywa śmierć dziecka; Borynowie walczą o ziemię; Makbetowie niszczą więź wspólną winą.',Poświęcenie:'Prometeusz cierpi za ludzi; Antygona oddaje życie za obowiązek; Jacek Soplica służy ojczyźnie; Rieux ryzykuje dla chorych; Edelman walczy o każde życie.','Granice człowieczeństwa':'Achilles odzyskuje empatię; Tadek przystosowuje się do obozu; więźniowie łagru są zmuszani do egoizmu; Edelman broni godności; Winston zostaje zmuszony do zdrady.',Totalitaryzm:'„Rok 1984” – kontrola prawdy; „Inny świat” – łagier; Borowski – obóz; Krall – Zagłada; „Dziady III” – wcześniejszy model państwowego terroru.',Absurd:'Syzyf jako archetyp; Camus – działanie bez gwarancji; Andrews – niezrozumiała codzienność stanu wojennego; „Tango” – groteskowy chaos; Orwell – dwójmyślenie.','Bunt przeciwko rzeczywistości':'Cezary nie przyjmuje żadnego programu; Konrad chce zmienić porządek świata; Artur odrzuca anarchię; Winston broni prywatnej prawdy; romantycy przeciwstawiają czucie racjonalizmowi.'};
function motifsView(){return `<div class="hero"><h2>Motyw → utwory → różnica → gotowy argument</h2><p>Nie zapamiętuj samej definicji. Wybierz dwie sceny, pokaż ich podobieństwo lub różnicę i sformułuj wniosek.</p></div><div class="grid">${motifNames.map((n,i)=>`<article class="card" data-result-id="motif-${i}" data-search="${n} ${motifExamples[n]||''}"><h2>${n}</h2><p><b>5 tekstów i co się w nich dzieje:</b> ${motifExamples[n]||'Dobierz pięć lektur, wskaż decyzję bohatera i jej konsekwencję.'}</p><p><b>Gotowy kierunek argumentu:</b> Motyw ${n.toLowerCase()} nie jest jedynie elementem fabuły – ujawnia wartości bohatera i sprawia, że ponosi on konsekwencje własnej postawy.</p><p><b>Jak porównać?</b> Sprawdź, czy bohater wybiera świadomie, czy działa pod presją; czy doświadczenie go rozwija, czy niszczy; czy tekst potwierdza podobny system wartości.</p></article>`).join('')}</div>`}
function philosophyView(){return `<div class="hero"><h2>Filozofia użyteczna na maturze</h2><p>Zapamiętaj ideę i jeden przykład – nie biografię filozofa.</p></div><div class="grid">${expanded.philosophies.map((x,i)=>`<article class="card" data-result-id="philosophy-${i}" data-search="${x.join(' ')}"><h2>${x[0]}</h2><p><b>Kto?</b> ${x[1]}</p><p><b>Co to znaczy?</b> ${x[2]}</p><p><b>Przykład z lektury:</b> ${x[3]}</p></article>`).join('')}</div>`}
function erasView(){const extra=[['Antyk','IX/VIII w. p.n.e.–V w. n.e.','polis greckie, demokracja ateńska, wojny, rozwój Rzymu i chrześcijaństwa','harmonia, mimesis, humanizm antyczny; człowiek podlega losowi, ale odpowiada za wybór','epos, tragedia, komedia, hymn, mit','Homer, Sofokles, Horacy; „Iliada”, „Antygona”, mity','fatum, heroizm, konflikt wartości, wina, sława','porządek, proporcja, idealizacja ciała; w tekście: bogowie, mit, retoryczność, zasada decorum'],['Średniowiecze','V–XV w.','upadek Rzymu, feudalizm, krucjaty, dominacja Kościoła','teocentryzm, uniwersalizm, dualizm duszy i ciała; życie jako droga do zbawienia','hagiografia, kronika, chanson de geste, plankt, moralitet','Gall Anonim, autorzy anonimowi; „Bogurodzica”, „Lament…”, „Pieśń o Rolandzie”','memento mori, ars moriendi, deesis, asceza, rycerz','hierarchia i symbol; w tekście: anonimowość, dydaktyzm, wzorce świętego, rycerza i władcy'],['Renesans','XV–XVI w.','odkrycia geograficzne, druk, reformacja, rozwój państw narodowych','humanizm, antropocentryzm, ad fontes, stoicyzm i epikureizm; człowiek może kształtować życie','pieśń, fraszka, tren, sonet, tragedia','Kochanowski, Szekspir; pieśni, „Treny”, „Makbet”','harmonia, fortuna, cnota, sława poetycka, obywatel','ład, perspektywa, antyczne wzorce; w tekście: sentencje, umiar, zainteresowanie jednostką'],['Barok','koniec XVI–połowa XVIII w.','kontrreformacja, wojny religijne, kryzysy polityczne','niepokój metafizyczny, kontrast ciało–dusza, vanitas, konceptyzm','sonet, pamiętnik, kazanie, poemat heroikomiczny','Morsztyn, Naborowski, Pasek','przemijanie, śmierć, miłość zmysłowa, Bóg, sarmatyzm','dynamika, przepych, światłocień; w tekście: paradoks, antyteza, zaskakujący koncept'],['Oświecenie','XVIII w.–1822 w Polsce','rewolucje, rozbiory Polski, rozwój nauki i prasy','racjonalizm, empiryzm, deizm, utylitaryzm; edukacja ma naprawiać społeczeństwo','satyra, bajka, komedia, poemat heroikomiczny','Krasicki, Naruszewicz; satyry, „Hymn do miłości ojczyzny”','rozum, reforma, patriotyzm, krytyka wad, tolerancja','klasycyzm i porządek; w tekście: ironia, dydaktyzm, typowe wady społeczne'],['Romantyzm','1822–1863/64','zabory, powstanie listopadowe, Wielka Emigracja','irracjonalizm, indywidualizm, historyzm, mesjanizm; jednostka wyjątkowa pozostaje w konflikcie ze światem','ballada, dramat romantyczny, poemat dygresyjny','Mickiewicz, Słowacki; „Dziady III”, „Pan Tadeusz”, ballady','bunt, miłość, naród, natura, ludowość, poeta-wieszcz','ruiny, noc, tajemniczość; w tekście: synkretyzm, fantastyka, wizje, otwarta kompozycja'],['Pozytywizm','1864–ok. 1890','klęska powstania styczniowego, industrializacja, urbanizacja','scjentyzm, realizm, organicyzm, utylitaryzm; jednostka działa dla rozwoju zbiorowości','powieść realistyczna, nowela, felieton','Prus, Sienkiewicz, Orzeszkowa; „Lalka”, „Potop”','praca, nauka, miasto, nierówność, emancypacja','realizm szczegółu; w tekście: narrator analizujący społeczeństwo i typowe środowiska'],['Młoda Polska','ok. 1890–1918','kryzys końca wieku, rozwój miast, rewolucja 1905','dekadentyzm, nietzscheanizm, symbolizm, chłopomania; artysta i jednostka czują kryzys wartości','dramat symboliczny, powieść naturalistyczna, liryk impresjonistyczny','Wyspiański, Reymont, Tetmajer; „Wesele”, „Chłopi”','marazm, artysta, natura, wieś, naród, katastrofizm','secesja, symbol i nastrój; w tekście: synestezje, wieloznaczne obrazy, naturalizm'],['Dwudziestolecie','1918–1939','niepodległość, wojna 1920, kryzys gospodarczy, totalitaryzmy','pluralizm: awangarda, katastrofizm, psychoanaliza, eksperyment; spór o nowoczesność i państwo','powieść polityczna, groteska, reportaż, poezja awangardowa','Żeromski, Gombrowicz; „Przedwiośnie”, „Ferdydurke”','dojrzewanie państwa, forma, rewolucja, miasto, technika','funkcjonalizm i awangarda; w tekście: eksperyment, groteska, język potoczny'],['Wojna i współczesność','1939–dziś','II wojna, Zagłada, komunizm, zimna wojna, transformacja','egzystencjalizm, personalizm, postmodernizm; pytanie o godność po katastrofie','opowiadanie obozowe, reportaż, parabola, antyutopia, dramat groteskowy','Borowski, Herling, Krall, Miłosz, Mrożek, Tokarczuk','świadectwo, totalitaryzm, pamięć, absurd, granice człowieczeństwa','różnorodność; w tekście: dokument, ironia, intertekstualność, fragmentaryczność']];return `<div class="hero"><h2>Jak rozpoznać epokę?</h2><p>Szukaj systemu wartości, typowych motywów, gatunku, sposobu przedstawienia człowieka oraz śladów historii – nie tylko dat.</p></div>${extra.map((e,i)=>`<article class="card" data-search="${e.join(' ')}"><h2>${e[0]}</h2><div class="era-grid"><p><b>Ramy:</b> ${e[1]}</p><p><b>Historia:</b> ${e[2]}</p><p><b>Światopogląd, filozofia i człowiek:</b> ${e[3]}</p><p><b>Gatunki:</b> ${e[4]}</p><p><b>Autorzy i lektury:</b> ${e[5]}</p><p><b>Motywy i hasła:</b> ${e[6]}</p><p><b>Sztuka i rozpoznawanie:</b> ${e[7]}</p></div></article>`).join('')}`}
function analysisView(){const items=[['Narrator','Kto opowiada? Czy uczestniczy w wydarzeniach? Czy zna myśli bohaterów? Pierwsza osoba zwiększa subiektywność, narrator wszechwiedzący pozwala szerzej ocenić świat.'],['Podmiot liryczny i adresat','Nie utożsamiaj automatycznie podmiotu z autorem. Ustal, kim jest mówiący, do kogo mówi, w jakiej sytuacji i z jakim nastawieniem.'],['Świat przedstawiony','Wypisz miejsce, czas, bohaterów i najważniejsze zdarzenia. Zwróć uwagę, czy przestrzeń jest realistyczna, symboliczna, zamknięta lub kontrastowa.'],['Bohater','Określ cel, motywację, konflikt, wybór, konsekwencje i przemianę. Cecha bez dowodu nie jest analizą – zawsze dodaj scenę.'],['Kompozycja','Sprawdź kolejność zdarzeń, klamrę, retrospekcję, punkt kulminacyjny, kontrasty, powtórzenia i zakończenie otwarte. Wyjaśnij, jak układ steruje interpretacją.'],['Język i styl','Nazwij dominujące słownictwo, składnię i ton: podniosły, potoczny, ironiczny, emocjonalny, rzeczowy. Potem wyjaśnij wpływ na odbiorcę.'],['Ironia','Dosłowny sens różni się od zamierzonego. Może ośmieszać bohatera, ujawniać hipokryzję albo tworzyć dystans narratora.'],['Symbol i alegoria','Symbol jest wieloznaczny i zależny od kontekstu; alegoria ma znaczenie utrwalone. Zawsze uzasadnij znaczenie elementami tekstu.'],['Groteska','Połączenie komizmu i grozy, deformacji i realizmu. Nie służy tylko śmiechowi – pokazuje chaos, kryzys norm lub absurd.'],['Kontrast','Zestawienie przeciwieństw eksponuje konflikt wartości, różnice bohaterów albo przemianę. Nazwij oba człony i wynik porównania.'],['Stylizacja','Autor naśladuje język epoki, środowiska lub gatunku. Stylizacja buduje wiarygodność, charakteryzuje postać albo tworzy parodię.'],['Funkcja środka','Użyj formuły: autor zastosował [środek], aby [efekt bezpośredni], co podkreśla [sens problemu]. Np. anafora wzmacnia rytm, przez co eksponuje natarczywość wezwania.']];return `<div class="hero"><h2>Analiza tekstu krok po kroku</h2><p>Najważniejsze pytanie brzmi nie „co tu jest?”, lecz „jak to działa i co dzięki temu rozumiem?”.</p></div><div class="grid">${items.map(x=>`<article class="card" data-search="${x.join(' ')}"><h2>${x[0]}</h2><p>${x[1]}</p></article>`).join('')}</div><div class="card"><h2>Uniwersalny schemat odpowiedzi</h2><p><b>Obserwacja:</b> W tekście pojawia się… <b>Dowód:</b> Widać to w… <b>Funkcja:</b> Ten zabieg powoduje… <b>Interpretacja:</b> Dzięki temu autor pokazuje, że…</p></div>`}
function genresView(){return `<div class="hero"><h2>Gatunki i rodzaje literackie</h2><p>Rozpoznaj cechy, nazwij przykład i wyjaśnij, jak forma wpływa na znaczenie utworu.</p></div><div class="card">${expanded.genres.map((r,i)=>`<div class="motif-row" data-result-id="genre-${i}" data-search="${r.join(' ')}"><b>${r[0]}</b><span>${r[1]}</span><span><b>Przykład:</b> ${r[2]}</span></div>`).join('')}</div>`}
const essayContent=window.ESSAY_CONTENT||{contexts:[],themes:[],essays:[]};
function essayComplete(){const guide=[['Najbezpieczniejsza forma','Wstęp z tezą → argument z lektury obowiązkowej → analiza sceny → kontekst → wniosek cząstkowy → drugi argument z innego utworu → drugi kontekst → porównanie → zakończenie. Taki układ jest czytelny i chroni przed streszczaniem.'],['Najważniejszy wzór','TEZA → ARGUMENT → PRZYKŁAD → WYJAŚNIENIE → KONTEKST → WNIOSEK. Każdy element musi odpowiadać tematowi. Jeśli usuniesz nazwę tematu i akapit nadal pasuje do każdej pracy, jest zbyt ogólny.'],['Jak zrobić dobry wstęp','Zdefiniuj problem własnymi słowami, pokaż jego niejednoznaczność i postaw stanowisko. Wystarczą 3–5 zdań. Wstęp ma przygotować tok rozumowania, a nie opowiadać historię literatury.'],['Czego nie pisać we wstępie','Unikaj: „od zarania dziejów”, „ludzie od zawsze”, definicji ze słownika bez interpretacji, biografii autora, streszczenia lektury, pytań bez odpowiedzi oraz zapowiedzi, których później nie realizujesz.'],['Teza – najważniejsze zdanie','Teza odpowiada dokładnie na pytanie i wskazuje zależność lub warunek. Zamiast „miłość jest ważna” napisz: „Miłość buduje człowieka, gdy opiera się na odpowiedzialności, lecz idealizacja może prowadzić do samotności i klęski”.'],['Jak napisać argument','Argument jest ogólnym twierdzeniem dowodzącym tezy, a nie wydarzeniem z fabuły. Najpierw nazwij prawidłowość, potem wybierz scenę. Po przykładzie obowiązkowo wyjaśnij: dlaczego ta scena potwierdza stanowisko?'],['Gotowy schemat akapitu','Po pierwsze, [ARGUMENT]. W [TYTUŁ] [AUTOR] bohater [KONKRETNA SYTUACJA]. Działa tak, ponieważ [MOTYWACJA], a konsekwencją jest [SKUTEK]. Pokazuje to, że [INTERPRETACJA]. Podobnie / odmiennie w [KONTEKST], gdzie [KRÓTKIE PORÓWNANIE]. Zatem [WNIOSEK CZĄSTKOWY].'],['Jak wykorzystać kontekst','Kontekst ma zmieniać lub pogłębiać rozumienie przykładu. Nazwij wspólne kryterium, podobieństwo albo różnicę. Nie dopisuj jedynie: „kontekstem jest Biblia”. Wyjaśnij, co porównanie z Hiobem mówi o cierpieniu bohatera.'],['Jak zakończyć pracę','Zbierz wyniki obu argumentów, odpowiedz ponownie na temat innymi słowami i wskaż warunek, różnicę albo szerszy wniosek. Nie dodawaj nowego utworu i nie kończ pustym zdaniem „każdy ma własne zdanie”.'],['Zwroty, które warto znać','Argument: „Los bohatera dowodzi, że…”. Analiza: „Decyzja wynika z…”, „Konsekwencją jest…”, „Scena ujawnia…”. Porównanie: „W obu utworach…, jednak…”, „Zasadnicza różnica polega na…”. Wniosek: „Zatem…”, „Ostatecznie przykład potwierdza…”.']];return `<div class="hero"><h2>Komplet do wypracowania maturalnego</h2><p>Nie ucz się gotowych zdań bez zrozumienia. Zapamiętaj konstrukcję dowodu i ćwicz ją na różnych tematach.</p></div><h2 class="section-title">Najbezpieczniejsza konstrukcja</h2><div class="essay-guide">${guide.map(x=>`<article class="card" data-search="${x.join(' ')}"><h2>${x[0]}</h2><p>${x[1]}</p></article>`).join('')}</div><h2 class="section-title">Najważniejsze konteksty do zapamiętania</h2><div class="context-bank">${essayContent.contexts.map(x=>`<div class="context-mini" data-search="${x.join(' ')}"><b>${x[0]}</b><p>${x[1]}</p><small>Połącz z: ${x[2]}</small></div>`).join('')}</div><h2 class="section-title">3 gotowe wypracowania z komentarzem</h2>${essayContent.essays.map((e,i)=>`<article class="card essay-example" data-search="${e.title} ${e.works} ${e.contexts}"><h2>${i+1}. ${e.title}</h2><div class="essay-meta"><span>Utwory: ${e.works}</span><span>Konteksty: ${e.contexts}</span><span>minimum 300 słów</span></div>${e.sections.map(s=>`<section class="essay-section ${s[0].startsWith('Komentarz')?'comment':''}"><h3>${s[0]}</h3><p>${s[1]}</p></section>`).join('')}</article>`).join('')}<h2 class="section-title">Tematy do samodzielnego napisania</h2><p class="card">Tekst zapisuje się automatycznie na urządzeniu i – po zalogowaniu – w chmurze. Licznik pomoże osiągnąć minimum 300 słów.</p>${essayContent.themes.map((t,i)=>`<article class="card practice-essay" data-search="${t}"><h2>${i+1}. ${t}</h2><textarea data-essay="essay-${i}" placeholder="Napisz tutaj własne wypracowanie…">${esc(essays['essay-'+i]||'')}</textarea><div class="word-counter"><span>Zapis automatyczny</span><b data-word-count="essay-${i}">0 słów</b></div></article>`).join('')}`}
function questionsView(){return `<div class="card oral-intro"><b>76 pytań • 76 gotowych odpowiedzi</b><p>Każda karta zawiera krótki plan oraz wypracowaną odpowiedź: tezę, przykład z lektury, analizę, kontekst i wniosek. Najpierw spróbuj odpowiedzieć samodzielnie, a potem rozwiń blok wzorcowy i porównaj tok rozumowania.</p></div>${questions.map(q=>`<details class="question" id="q${q[0]}" data-id="q${q[0]}" data-search="${q.join(' ')} ${(highlights['q'+q[0]]||[]).map(h=>h.quote+' '+h.note).join(' ')}"><summary>${q[0]}. ${q[2]} <span class="meta">— ${q[1]}</span></summary><div class="answer"><div class="selectable-text">${qAnswer(q)}</div>${check('q'+q[0],'Umiem odpowiedzieć samodzielnie')}${annotationsBox('q'+q[0])}</div></details>`).join('')}<p class="source">Lista pytań: komunikat CKE z 30 sierpnia 2024 r. obowiązujący w latach 2026–2028. Odpowiedzi są materiałem treningowym — warto dostosować słownictwo do własnego sposobu mówienia.</p>`}
function labelFor(id){if(id.startsWith('page-')){const page=id.slice(5),entry=nav.find(x=>x[0]===page);return {isQ:false,label:entry?entry[1]:'Dział tematyczny',type:'Dział'}}if(id[0]==='s'){const w=expanded.shortWorks[Number(id.slice(1))];return {isQ:false,label:w?.t||'Lektura uzupełniająca',type:'Lektura CKE'}}if(id[0]==='p'){const w=expanded.poems[Number(id.slice(1))];return {isQ:false,label:w?.[0]||'Wiersz',type:'Poezja'}}const isQ=id[0]==='q',item=isQ?questions.find(q=>q[0]===id.slice(1)):books[Number(id.slice(1))];return {isQ,label:isQ?(item?item[0]+'. '+item[2]:'Pytanie'):(item?item[0]:'Lektura'),type:isQ?'Pytanie jawne':'Lektura'}}
function mynotes(){const rows=Object.entries(highlights).flatMap(([id,list])=>{const info=labelFor(id);return list.map(h=>`<article class="card own-note" data-search="${esc(info.label+' '+h.quote+' '+h.note)}"><h3>${esc(info.label)}</h3><div class="meta">${info.type}</div><blockquote class="annotation-quote">„${esc(h.quote)}”</blockquote><textarea data-annotation-note="${id}" data-highlight-id="${h.id}" placeholder="Dopisz własną notatkę…">${esc(h.note||'')}</textarea><button class="note-link" data-goto="${id}">Przejdź do materiału</button></article>`)}).join('');return `<div class="hero"><h2>Moje notatki ♡</h2><p>Tu znajdziesz wszystkie zaznaczone fragmenty i własne dopiski. Każdą notatkę możesz dalej edytować.</p></div><h2 class="section-title">Notatki z zaznaczeń</h2><div class="notes-list">${rows||'<div class="card empty">Nie masz jeszcze notatek. Zaznacz fragment tekstu w dowolnym dziale i wybierz „Dodaj notatkę”.</div>'}</div>`}
function heroes(){return `<div class="grid">${books.map((b,i)=>`<div class="card" data-search="${b[0]} ${b[4]}"><h3>${b[0]}</h3><p>${b[4]}</p></div>`).join('')}</div>`}
function essay(){const cards=[['Jak rozpoznać temat','Podkreśl pojęcie główne, zakres i czasownik polecenia. Jeśli temat pyta „jaką rolę”, nie wystarczy udowodnić samo istnienie motywu – trzeba nazwać jego funkcję i skutek. Zapisz roboczo: o czym mam rozstrzygnąć?'],['Jak stworzyć tezę','Teza musi odpowiadać na cały temat i dawać się udowodnić. Dobra teza wskazuje zależność: „Cierpienie może prowadzić do dojrzewania, jeśli człowiek nada mu sens i przyjmie odpowiedzialność”. Unikaj oczywistości typu „cierpienie jest ważne”.'],['Jak dobrać lekturę','Wybierz tekst, w którym pamiętasz konkretną scenę, przyczynę działania oraz konsekwencję. Znana scena jest lepsza niż ambitny tytuł przywołany ogólnikowo. Sprawdź też, czy utwór naprawdę odpowiada słowu kluczowemu z tematu.'],['Argument a przykład','Argument to ogólne twierdzenie dowodzące tezy. Przykład to scena z utworu. „Makbet zabija Dunkana” jest przykładem; „przekroczenie pierwszej granicy moralnej ułatwia kolejne zbrodnie” jest argumentem.'],['Analiza przykładu','Omów tylko elementy potrzebne do dowodu: sytuacja → motywacja → decyzja → skutek → znaczenie. Po scenie dodaj zdanie „Pokazuje to, że…”, które łączy przykład z argumentem.'],['Wniosek cząstkowy','Na końcu akapitu wróć do tezy innymi słowami. Nie dodawaj nowego wydarzenia. Wniosek ma pokazać, co zostało dowiedzione i dlaczego jest ważne dla tematu.'],['Kontekst funkcjonalny','Kontekst nie jest dopisanym tytułem. Nazwij podobieństwo lub różnicę i wyjaśnij, jak zmienia rozumienie argumentu. Może być literacki, historyczny, filozoficzny, biblijny, mitologiczny lub związany ze sztuką.'],['Porównanie tekstów','Ustal wspólne kryterium, np. źródło buntu. „Antygona buntuje się w obronie prawa boskiego, Winston – prywatnej prawdy; oboje bronią wartości, lecz tylko system totalitarny potrafi zniszczyć wewnętrzną niezależność bohatera”.'],['Zakończenie','Nie powtarzaj mechanicznie wstępu. Zbierz wyniki obu argumentów, wskaż różnicę albo warunek i sformułuj szerszy wniosek. Nie wprowadzaj nowej lektury.'],['Pułapki maturalne','Streszczanie zamiast argumentowania; bohater bez sceny; kontekst bez związku z tezą; błędne nazwiska i wydarzenia; mylenie autora z narratorem; brak wniosku; lanie wody; używanie słów „zawsze” i „każdy” bez uzasadnienia.']];return `<div class="hero"><h2>Wypracowanie – od tematu do wniosku</h2><p>Najbezpieczniejszy akapit: <b>argument → scena → analiza → kontekst → wniosek cząstkowy</b>.</p></div><div class="grid">${cards.map(x=>`<article class="card" data-search="${x.join(' ')}"><h2>${x[0]}</h2><p>${x[1]}</p></article>`).join('')}</div><h2 class="section-title">Bank przydatnego języka</h2><div class="card"><p><b>Wprowadzanie argumentu:</b> Po pierwsze; Istotnym źródłem…; Los bohatera dowodzi, że…</p><p><b>Analiza:</b> Decyzja ta wynika z…; Konsekwencją jest…; Scena ujawnia…; Autor podkreśla w ten sposób…</p><p><b>Porównanie:</b> Podobnie; Odmiennie; W obu tekstach…, jednak…; Zasadnicza różnica polega na…</p><p><b>Wnioskowanie:</b> Zatem; Wynika z tego, że…; Ostatecznie przykład potwierdza…; Można więc uznać…</p></div><h2 class="section-title">Wzorcowy miniakapit</h2><div class="card"><p><b>Żądza władzy niszczy granice moralne człowieka.</b> Makbet, zachęcony przepowiednią i naciskiem żony, zabija Dunkana, chociaż wie, że król jest jego gościem i prawowitym władcą. Po zdobyciu korony nie odzyskuje spokoju: zleca następne morderstwa, ponieważ każda zbrodnia rodzi lęk przed utratą pozycji. <b>Pokazuje to, że władza uzyskana przemocą uzależnia sprawcę od kolejnej przemocy.</b> Podobny mechanizm w „Balladynie” potwierdza, że usuwanie świadków nie usuwa winy, tylko pogłębia samotność bohatera. Zatem ambicja pozbawiona zasad prowadzi nie do wolności, lecz do moralnego zniewolenia.</p></div>`}
function speaking(){return `<div class="hero"><h2>Odpowiedź ustna w 6 ruchach</h2><p>Nie ucz się całych tekstów na pamięć. Zapamiętaj tok rozumowania i 2–3 sceny z każdej lektury.</p></div><div class="grid">${[['1. Wprowadzenie','Wyjaśnij pojęcie z pytania i zawęź problem.'],['2. Teza','Odpowiedz na pytanie jednym jasnym zdaniem.'],['3. Argument','Nazwij prawidłowość, którą pokaże lektura.'],['4. Przykład','Omów konkretną scenę: przyczyna → decyzja → skutek.'],['5. Kontekst','Porównaj z innym utworem, historią, filozofią lub sztuką.'],['6. Wniosek','Wróć do pytania i pokaż, co wynika z porównania.']].map(x=>`<div class="card"><h3>${x[0]}</h3><p>${x[1]}</p></div>`).join('')}</div><h2 class="section-title">Gotowy szablon językowy</h2><div class="card"><p>„Zagadnienie … dotyczy … . Uważam, że … . Potwierdza to … w utworze … . Bohater …, ponieważ …, dlatego … . Skutkiem jego decyzji jest … . Podobny / odmienny sposób ujęcia widzimy w … . Ten kontekst pokazuje, że … . Można więc stwierdzić, że … .”</p></div>`}
function examTask(task,number){const saved=examAnswers[task.id]??'';const answer=task.type==='choice'?`<div class="exam-options">${task.options.map((option,i)=>`<label class="exam-option"><input type="radio" name="${task.id}" data-exam-answer="${task.id}" value="${i}" ${String(saved)===String(i)?'checked':''}><span>${esc(option)}</span></label>`).join('')}</div>`:`<textarea class="exam-answer" data-exam-answer="${task.id}" placeholder="Wpisz odpowiedź…">${esc(saved)}</textarea>`;return `<article class="card exam-task"><div class="exam-task-head"><h3>Zadanie ${number}</h3><span class="exam-points">${task.points} ${task.points===1?'punkt':'punkty'}</span></div><p>${esc(task.question)}</p>${answer}</article>`}
function examView(){if(!polishExam)return '<div class="card">Nie udało się wczytać arkusza. Odśwież stronę.</div>';let number=0;const sections=polishExam.sections.map(section=>`<h2 class="section-title">${esc(section.title)} • ${section.max} pkt</h2>${section.tasks.map(task=>examTask(task,++number)).join('')}`).join('');const essay=polishExam.essay,essayText=examAnswers[essay.id]||'',topic=examAnswers[essay.id+'-topic']||'';return `<div class="hero"><h2>${esc(polishExam.title)}</h2><p>Autorski arkusz treningowy zgodny ze strukturą egzaminu CKE. Odpowiedzi zapisują się automatycznie lokalnie i na zalogowanym koncie.</p><div class="exam-info"><span>⏱ ${polishExam.duration} minut</span><span>★ ${polishExam.maxPoints} punktów</span><span>✎ 3 części</span></div><p class="exam-source">To nie jest kopia oficjalnego arkusza. <a href="${polishExam.sourceUrl}" target="_blank" rel="noopener">Zobacz oficjalne materiały CKE</a>.</p></div><h2 class="section-title">Teksty źródłowe</h2>${polishExam.texts.map(text=>`<article class="exam-text selectable-text"><h3>${esc(text.title)}</h3><p>${esc(text.body)}</p></article>`).join('')}${sections}<h2 class="section-title">Część 3. Wypracowanie • ${essay.points} pkt</h2><article class="card exam-task"><p><b>${esc(essay.requirements)}</b></p><div class="exam-options">${essay.topics.map((item,i)=>`<label class="exam-option"><input type="radio" name="exam-topic" data-exam-answer="${essay.id}-topic" value="${i}" ${String(topic)===String(i)?'checked':''}><span><b>Temat ${i+1}.</b> ${esc(item)}</span></label>`).join('')}</div><textarea class="exam-answer exam-essay" data-exam-answer="${essay.id}" placeholder="Napisz tutaj wypracowanie…">${esc(essayText)}</textarea><div class="word-counter"><span>Minimum ${essay.minWords} słów</span><b id="examWordCount">0 słów</b></div></article><div class="exam-actions"><span class="exam-grade-status" id="examGradeStatus">Wypełnij arkusz, a następnie poproś ChatGPT o ocenę.</span><button id="gradeExam" type="button">Oceń maturę w ChatGPT</button></div>`}
function examPrompt(){const lines=[],closed=[];for(const section of polishExam.sections){lines.push(`\n${section.title}`);for(const task of section.tasks){const raw=examAnswers[task.id];let value='BRAK ODPOWIEDZI';if(task.type==='choice'&&raw!==undefined&&raw!=='')value=task.options[Number(raw)]||'BRAK ODPOWIEDZI';else if(raw)value=raw;lines.push(`Zadanie ${task.id} (${task.points} pkt): ${task.question}\nOdpowiedź ucznia: ${value}\nKlucz/kryterium: ${task.type==='choice'?task.options[task.answer]+' — '+task.explain:task.rubric}`);if(task.type==='choice')closed.push(task)}}const topicIndex=examAnswers[polishExam.essay.id+'-topic'],topic=polishExam.essay.topics[Number(topicIndex)]||'NIE WYBRANO TEMATU',essay=examAnswers[polishExam.essay.id]||'BRAK WYPRACOWANIA';return `Oceń poniższy autorski arkusz treningowy matury podstawowej z języka polskiego. Odpowiadaj po polsku. Oceń każde zadanie osobno zgodnie z podanym kluczem, nie dopisuj punktów ponad maksimum. Przy każdym błędzie podaj: co jest błędne lub niepełne, poprawną odpowiedź i krótkie wyjaśnienie. Następnie oceń wypracowanie w skali 0–30, uwzględniając realizację tematu, lekturę obowiązkową, drugi utwór, co najmniej dwa konteksty, argumentację, kompozycję, spójność, styl, język, ortografię i interpunkcję oraz minimum 300 słów. Zwróć tabelę: zadanie | punkty | maksimum | komentarz, sumę /60, procent i 5 najważniejszych rzeczy do poprawy.${lines.join('\n')}\n\nWYPRACOWANIE (30 pkt)\nWybrany temat: ${topic}\nWymagania: ${polishExam.essay.requirements}\nKryteria: ${polishExam.essay.rubric}\nTekst ucznia:\n${essay}`}
async function gradeExamWithChatGPT(){if(!polishExam)return;const prompt=examPrompt(),closed=polishExam.sections.flatMap(s=>s.tasks).filter(t=>t.type==='choice'),earned=closed.reduce((sum,t)=>sum+(String(examAnswers[t.id])===String(t.answer)?t.points:0),0),maximum=closed.reduce((sum,t)=>sum+t.points,0),status=document.querySelector('#examGradeStatus');try{await navigator.clipboard.writeText(prompt)}catch(e){}if(prompt.length<7000)window.open('https://chatgpt.com/?q='+encodeURIComponent(prompt),'_blank','noopener,noreferrer');else window.open('https://chatgpt.com/','_blank','noopener,noreferrer');status.textContent=`Zamknięte: ${earned}/${maximum} pkt. ${prompt.length<7000?'Otwarto pełną ocenę w ChatGPT.':'Arkusz skopiowano — w nowym oknie wklej go skrótem Ctrl+V.'}`;toast('Arkusz przekazany do oceny w ChatGPT')}
const views={start,exam:examView,books:booksView,shortworks:shortWorksView,poetry:poetryView,motifs:motifsView,oral:questionsView,mynotes,heroes,contexts:()=>tableView(contexts),eras:erasView,philosophy:philosophyView,analysis:analysisView,devices:()=>tableView(devices),genres:genresView,essay:essayComplete,speaking};
const content=document.querySelector('#content'),navEl=document.querySelector('#nav'),title=document.querySelector('#pageTitle');
function render(keepScroll=false){const y=window.scrollY;title.textContent=nav.find(x=>x[0]===state.page)[1];content.innerHTML=views[state.page]();if(!content.querySelector('[data-id]')&&!['start','mynotes'].includes(state.page)){const pageId='page-'+state.page;content.dataset.id=pageId;content.classList.add('selectable-text');content.insertAdjacentHTML('beforeend',annotationsBox(pageId))}else{content.removeAttribute('data-id');content.classList.remove('selectable-text')}renderNav();applyHighlights();filter();bindInputs();if(keepScroll)window.scrollTo(0,y);else window.scrollTo(0,0)}
function filter(){const q=normalizeText(state.query);let any=false;content.querySelectorAll('[data-search]').forEach(el=>{const hay=normalizeText(el.dataset.search),exact=!q||hay.includes(q),words=hay.split(' '),fuzzy=q.length>=3&&words.some(w=>Math.abs(w.length-q.length)<=2&&1-editDistance(q,w)/Math.max(q.length,w.length,1)>=.68),matches=exact||fuzzy,selected=!state.selectedOnly||done[el.dataset.id];const show=matches&&selected;el.style.display=show?'':'none';if(show)any=true});content.querySelectorAll('.filter-empty').forEach(x=>x.remove());if((q||state.selectedOnly)&&!any)content.insertAdjacentHTML('beforeend','<div class="empty filter-empty">Brak pasujących materiałów. Wybierz wynik z globalnej listy albo wpisz krótszą frazę.</div>')}
function autoSizeNote(x){if(!x)return;x.style.height='auto';x.style.height=Math.max(72,x.scrollHeight)+'px';x.style.overflowY='hidden'}
function bindInputs(){document.querySelectorAll('[data-done]').forEach(x=>x.onchange=()=>{done[x.dataset.done]=x.checked;persist();progress();filter()});document.querySelectorAll('[data-note]').forEach(x=>{autoSizeNote(x);x.oninput=()=>{notes[x.dataset.note]=x.value;autoSizeNote(x);persist()}});document.querySelectorAll('[data-annotation-note]').forEach(x=>{autoSizeNote(x);x.oninput=()=>{const h=(highlights[x.dataset.annotationNote]||[]).find(v=>v.id===x.dataset.highlightId);if(h)h.note=x.value;autoSizeNote(x);persist()}});document.querySelectorAll('[data-essay]').forEach(x=>{const update=()=>{essays[x.dataset.essay]=x.value;const count=x.value.trim()?x.value.trim().split(/\s+/).length:0,box=document.querySelector(`[data-word-count="${x.dataset.essay}"]`);if(box){box.textContent=count+' słów';box.style.color=count>=300?'#25824a':''}persist()};x.oninput=update;const count=x.value.trim()?x.value.trim().split(/\s+/).length:0,box=document.querySelector(`[data-word-count="${x.dataset.essay}"]`);if(box)box.textContent=count+' słów'});document.querySelectorAll('[data-exam-answer]').forEach(x=>{const save=()=>{examAnswers[x.dataset.examAnswer]=x.value;persist();if(x.dataset.examAnswer==='e15'){const count=x.value.trim()?x.value.trim().split(/\s+/).length:0,box=document.querySelector('#examWordCount');if(box){box.textContent=count+' słów';box.style.color=count>=300?'#25824a':''}}};x.oninput=save;x.onchange=save});const examText=document.querySelector('[data-exam-answer="e15"]'),examCount=document.querySelector('#examWordCount');if(examText&&examCount){const count=examText.value.trim()?examText.value.trim().split(/\s+/).length:0;examCount.textContent=count+' słów';examCount.style.color=count>=300?'#25824a':''}const grade=document.querySelector('#gradeExam');if(grade)grade.onclick=gradeExamWithChatGPT}
function applyHighlights(){document.querySelectorAll('[data-id]').forEach(container=>{for(const h of highlights[container.dataset.id]||[]){const root=container.matches('.selectable-text')?container:(container.querySelector('.selectable-text')||container),walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(node.parentElement.closest('mark,textarea,button,.annotations')||!node.data.includes(h.quote))continue;const at=node.data.indexOf(h.quote),before=node.splitText(at);before.splitText(h.quote.length);const mark=document.createElement('mark');mark.className='user-highlight';mark.dataset.highlightId=h.id;before.replaceWith(mark);mark.append(before);break}}})}
function addHighlight(withNote){if(!pendingSelection)return;const {materialId,quote,existingHighlightId}=pendingSelection;if(existingHighlightId){if(withNote){const input=document.querySelector(`[data-annotation-note="${materialId}"][data-highlight-id="${existingHighlightId}"]`);hideSelectionTools();if(input){input.focus();input.scrollIntoView({behavior:'smooth',block:'center'})}}else{highlights[materialId]=(highlights[materialId]||[]).filter(h=>h.id!==existingHighlightId);hideSelectionTools();persist();render(true);toast('Usunięto podświetlenie')}return}const id=Date.now().toString(36)+Math.random().toString(36).slice(2,6);(highlights[materialId]||(highlights[materialId]=[])).push({id,quote,note:''});hideSelectionTools();persist();render(true);if(withNote)setTimeout(()=>{const input=document.querySelector(`[data-annotation-note="${materialId}"][data-highlight-id="${id}"]`);if(input){input.focus();input.scrollIntoView({behavior:'smooth',block:'center'})}},50)}
function openAskChatGPT(){if(!pendingSelection)return;askSelection={...pendingSelection};const info=labelFor(askSelection.materialId);askSelection.label=info.label;document.querySelector('#askQuote').textContent=askSelection.quote;document.querySelector('#askQuestion').value='';document.querySelector('#selectionTools').classList.remove('show');document.querySelector('#askDialog').showModal();setTimeout(()=>document.querySelector('#askQuestion').focus(),80)}
async function submitAskChatGPT(){if(!askSelection)return;const question=document.querySelector('#askQuestion').value.trim()||'Wyjaśnij ten fragment bardzo dokładnie, prostym językiem. Podaj jego znaczenie, związek z utworem, najważniejsze motywy oraz sposób wykorzystania w wypracowaniu maturalnym.';const prompt=`Jestem uczniem przygotowującym się do matury z języka polskiego 2027. Materiał: ${askSelection.label}.\n\nWybrany fragment:\n„${askSelection.quote}”\n\nMoje pytanie: ${question}\n\nOdpowiedz po polsku, rzeczowo i szczegółowo. Wyjaśnij pojęcia, podaj konkretny przykład z tekstu i pokaż, jak wykorzystać tę wiedzę w argumentacji maturalnej. Na końcu zaproponuj dwa pytania, które pomogą mi sprawdzić zrozumienie.`;try{await navigator.clipboard.writeText(prompt)}catch(e){}const url='https://chatgpt.com/?q='+encodeURIComponent(prompt);window.open(url,'_blank','noopener,noreferrer');document.querySelector('#askDialog').close();hideSelectionTools();toast('Otwarto rozmowę w ChatGPT')}
function hideSelectionTools(){document.querySelector('#selectionTools').classList.remove('show');pendingSelection=null;window.getSelection()?.removeAllRanges()}
function captureSelection(event){if(event?.target?.closest?.('input,textarea,select,button,label,nav'))return;setTimeout(()=>{const sel=window.getSelection(),quote=sel?.toString().trim();if(!quote||quote.length<2||quote.length>600){if(!event?.target?.closest?.('#selectionTools'))hideSelectionTools();return}const node=sel.anchorNode?.nodeType===3?sel.anchorNode.parentElement:sel.anchorNode;if(node?.closest?.('.annotations')){hideSelectionTools();return}const selectable=node?.closest?.('.selectable-text'),material=selectable?.closest('[data-id]')||(selectable?.matches?.('[data-id]')?selectable:null);if(!material){hideSelectionTools();return}const existingHighlightId=node?.closest?.('mark.user-highlight')?.dataset.highlightId||(highlights[material.dataset.id]||[]).find(h=>h.quote===quote)?.id||null,rect=sel.getRangeAt(0).getBoundingClientRect(),tools=document.querySelector('#selectionTools'),highlightButton=tools.querySelector('[data-selection-action="highlight"]');pendingSelection={materialId:material.dataset.id,quote,existingHighlightId};highlightButton.textContent=existingHighlightId?'✕ Odznacz':'🖍 Podświetl';tools.style.left=Math.max(8,Math.min(window.innerWidth-260,rect.left+rect.width/2-120))+'px';tools.style.top=Math.max(8,rect.top-52)+'px';tools.classList.add('show')},0)}
function progress(){const total=books.length+expanded.shortWorks.length+expanded.poems.length+questions.length,n=Object.values(done).filter(Boolean).length,p=Math.min(100,Math.round(n/total*100));document.querySelector('#progressText').textContent=p+'%';document.querySelector('#progressBar').style.width=p+'%'}
function localSave(){localStorage.setItem('maturaDone',JSON.stringify(done));localStorage.setItem('maturaNotes',JSON.stringify(notes));localStorage.setItem('maturaHighlights',JSON.stringify(highlights));localStorage.setItem('maturaEssays',JSON.stringify(essays));localStorage.setItem('maturaExamAnswers',JSON.stringify(examAnswers));localStorage.setItem('maturaQuizHistory',JSON.stringify(quizHistory))}
function persist(){localSave();clearTimeout(saveTimer);saveTimer=setTimeout(syncToCloud,650)}
function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(el._t);el._t=setTimeout(()=>el.classList.remove('show'),2400)}
const cfg=window.VADEMECUM_CONFIG||{},cloudReady=cfg.supabaseUrl&&cfg.supabaseAnonKey&&window.supabase;
const db=cloudReady?window.supabase.createClient(cfg.supabaseUrl,cfg.supabaseAnonKey):null;
async function syncToCloud(){if(!db||!currentUser)return;document.querySelector('#syncState').textContent='Zapisywanie…';const {error}=await db.from('vademecum_user_data').upsert({user_id:currentUser.id,payload:{done,notes,highlights,essays,examAnswers,quizHistory},updated_at:new Date().toISOString()});document.querySelector('#syncState').textContent=error?'Błąd zapisu':'Zapisano w chmurze';if(error)toast('Nie udało się zsynchronizować. Dane zostały lokalnie.')}
async function loadCloud(){if(!db||!currentUser)return;document.querySelector('#syncState').textContent='Synchronizacja…';const {data,error}=await db.from('vademecum_user_data').select('payload').eq('user_id',currentUser.id).maybeSingle();if(data?.payload){done=data.payload.done||{};notes=data.payload.notes||{};highlights=data.payload.highlights||{};essays=data.payload.essays||{};examAnswers=data.payload.examAnswers||{};quizHistory=data.payload.quizHistory||{};localSave()}else if(!error){await syncToCloud()}document.querySelector('#syncState').textContent=error?'Zapis lokalny':'Zapisano w chmurze';render();progress()}
function accountUI(){const b=document.querySelector('#accountBtn');b.textContent=currentUser?'◉ '+currentUser.email.split('@')[0]:'♡ Zaloguj się';document.querySelector('#syncState').textContent=currentUser?'Zapisano w chmurze':'Zapis lokalny'}
async function initAuth(){if(!db){accountUI();return}const {data}=await db.auth.getSession();currentUser=data.session?.user||null;accountUI();if(currentUser)await loadCloud();db.auth.onAuthStateChange((event,session)=>{currentUser=session?.user||null;accountUI()})}
function openAuth(){if(currentUser){if(confirm('Wylogować się z konta?'))db.auth.signOut().then(()=>{currentUser=null;accountUI();toast('Wylogowano')});return}if(!cloudReady){toast('Najpierw uzupełnij config.js danymi Supabase');return}document.querySelector('#authDialog').showModal()}
async function submitAuth(){const email=document.querySelector('#authEmail').value.trim(),password=document.querySelector('#authPassword').value,err=document.querySelector('#authError'),btn=document.querySelector('#authSubmit');err.textContent='';if(!email||password.length<6){err.textContent='Podaj poprawny e-mail i hasło mające co najmniej 6 znaków.';return}btn.disabled=true;btn.textContent='Chwileczkę…';const result=isRegister?await db.auth.signUp({email,password}):await db.auth.signInWithPassword({email,password});btn.disabled=false;btn.textContent=isRegister?'Utwórz konto':'Zaloguj się';if(result.error){err.textContent=result.error.message;return}if(result.data.session){currentUser=result.data.user;document.querySelector('#authDialog').close();accountUI();await loadCloud();toast('Zalogowano i zsynchronizowano dane')}else{err.textContent='Sprawdź pocztę i kliknij link potwierdzający konto.'}}
document.addEventListener('click',e=>{const quiz=e.target.closest('[data-quiz]');if(quiz){startQuiz(quiz.dataset.quiz);return}const closeQuiz=e.target.closest('[data-close-quiz]');if(closeQuiz){document.querySelector('#quizDialog')?.close();return}const nextQuiz=e.target.closest('[data-next-quiz]');if(nextQuiz){document.querySelector('#quizDialog')?.close();startQuiz(nextQuiz.dataset.nextQuiz);return}const action=e.target.closest('[data-selection-action]');if(action){if(action.dataset.selectionAction==='chatgpt')openAskChatGPT();else addHighlight(action.dataset.selectionAction==='note');return}const del=e.target.closest('[data-delete-highlight]');if(del){highlights[del.dataset.deleteHighlight]=(highlights[del.dataset.deleteHighlight]||[]).filter(h=>h.id!==del.dataset.highlightId);persist();render(true);toast('Usunięto zaznaczenie');return}const b=e.target.closest('[data-page]');if(b){state.page=b.dataset.page;state.query='';document.querySelector('#search').value='';render();document.querySelector('#sidebar').classList.remove('open')}const go=e.target.closest('[data-goto]');if(go){const id=go.dataset.goto;state.page=id.startsWith('page-')?id.slice(5):(id[0]==='q'?'oral':id[0]==='s'?'shortworks':id[0]==='p'?'poetry':'books');render();setTimeout(()=>{const el=document.querySelector(`[data-id="${id}"]`);if(el){if(el.tagName==='DETAILS')el.open=true;el.scrollIntoView({behavior:'smooth',block:'center'});el.classList.add('search-hit');setTimeout(()=>el.classList.remove('search-hit'),1600)}},50)}});
document.addEventListener('mouseup',captureSelection);
document.addEventListener('touchend',captureSelection);
document.addEventListener('mousedown',e=>{if(!e.target.closest('input,textarea,select,button,label,nav,#selectionTools,.selectable-text'))hideSelectionTools()});
const searchInput=document.querySelector('#search');
searchInput.addEventListener('input',e=>{state.query=e.target.value;showGlobalResults(e.target.value);filter()});
searchInput.addEventListener('click',e=>{e.stopPropagation();searchInput.focus()});
searchInput.addEventListener('touchend',e=>{e.stopPropagation();setTimeout(()=>searchInput.focus(),0)},{passive:true});
searchInput.addEventListener('focus',()=>showGlobalResults(searchInput.value));
searchInput.addEventListener('keydown',e=>{if(e.key==='Enter'){const first=document.querySelector('.search-result');if(first){e.preventDefault();openSearchResult(first.dataset.searchJump,first.dataset.searchId,first.dataset.searchTitle)}}if(e.key==='Escape')document.querySelector('#searchResults').classList.remove('show')});
document.querySelector('#searchResults').addEventListener('click',e=>{const item=e.target.closest('[data-search-jump]');if(item)openSearchResult(item.dataset.searchJump,item.dataset.searchId,item.dataset.searchTitle)});
document.addEventListener('click',e=>{if(!e.target.closest('.search-wrap'))document.querySelector('#searchResults').classList.remove('show')});
document.querySelector('#selectedOnly').addEventListener('change',e=>{state.selectedOnly=e.target.checked;filter()});
document.querySelector('#menu').onclick=()=>document.querySelector('#sidebar').classList.toggle('open');
document.querySelector('#accountBtn').onclick=openAuth;
document.querySelector('#authSubmit').onclick=submitAuth;
document.querySelector('#authSwitch').onclick=()=>{isRegister=!isRegister;document.querySelector('#authTitle').textContent=isRegister?'Utwórz konto':'Zaloguj się';document.querySelector('#authSubmit').textContent=isRegister?'Utwórz konto':'Zaloguj się';document.querySelector('#authSwitch').textContent=isRegister?'Masz już konto? Zaloguj się':'Nie masz konta? Zarejestruj się';document.querySelector('#authError').textContent=''};
document.querySelector('#askSubmit').onclick=submitAskChatGPT;
document.querySelector('#randomBtn').onclick=()=>{const q=questions[Math.floor(Math.random()*questions.length)];state.page='oral';state.query='';render();setTimeout(()=>{const el=document.querySelector('#q'+q[0]);el.open=true;el.scrollIntoView({behavior:'smooth',block:'center'})},50)};
render();progress();initAuth();
